package vn.edu.hunre.nhom11.carrental.shared.config;
import java.math.BigDecimal;import org.springframework.boot.CommandLineRunner;import org.springframework.context.annotation.Bean;import org.springframework.context.annotation.Configuration;import org.springframework.security.crypto.password.PasswordEncoder;import vn.edu.hunre.nhom11.carrental.catalog.domain.*;import vn.edu.hunre.nhom11.carrental.catalog.repository.*;import vn.edu.hunre.nhom11.carrental.content.domain.News;import vn.edu.hunre.nhom11.carrental.content.repository.NewsRepository;import vn.edu.hunre.nhom11.carrental.identity.domain.*;import vn.edu.hunre.nhom11.carrental.identity.repository.UserRepository;
@Configuration public class DataSeeder{@Bean CommandLineRunner seed(UserRepository users,PasswordEncoder encoder,BrandRepository brands,CarTypeRepository types,CarRepository cars,NewsRepository news){return args->{if(users.count()>0)return;User admin=user("Quản trị viên","admin@carrental.vn","Admin@123",Role.ADMIN,encoder);User customer=user("Khách hàng mẫu","customer@carrental.vn","Customer@123",Role.CUSTOMER,encoder);users.save(admin);users.save(customer);Brand toyota=brand("Toyota",brands),vinfast=brand("VinFast",brands),kia=brand("Kia",brands);CarType sedan=type("Sedan",5,types),suv=type("SUV",7,types),electric=type("Xe điện",5,types);car("Toyota Camry 2.0Q","30A-123.45",new BigDecimal("1200000"),"Sedan rộng rãi, tiết kiệm và phù hợp cho chuyến công tác.","Hà Nội",2025,toyota,sedan,"https://images.unsplash.com/photo-1621007947382-bb3c3994e3fb?auto=format&fit=crop&w=1200&q=80",cars);car("VinFast VF 8","30E-888.88",new BigDecimal("1650000"),"SUV điện hiện đại, khoang xe yên tĩnh và nhiều công nghệ an toàn.","Hà Nội",2025,vinfast,electric,"https://images.unsplash.com/photo-1619767886558-efdc259cde1a?auto=format&fit=crop&w=1200&q=80",cars);car("Kia Carnival Signature","29A-567.89",new BigDecimal("2200000"),"MPV 7 chỗ cao cấp cho gia đình và nhóm bạn.","Nội Bài",2024,kia,suv,"https://images.unsplash.com/photo-1549399542-7e3f8b79c341?auto=format&fit=crop&w=1200&q=80",cars);News n=new News();n.setTitle("Kinh nghiệm thuê xe tự lái an toàn");n.setContent("Kiểm tra giấy tờ, tình trạng xe và đọc kỹ điều khoản trước khi nhận xe.");news.save(n);};}
private User user(String n,String e,String p,Role r,PasswordEncoder encoder){User u=new User();u.setName(n);u.setEmail(e);u.setPassword(encoder.encode(p));u.setRole(r);return u;}private Brand brand(String n,BrandRepository r){Brand b=new Brand();b.setName(n);return r.save(b);}private CarType type(String n,int s,CarTypeRepository r){CarType t=new CarType();t.setName(n);t.setSeats(s);return r.save(t);}private void car(String n,String plate,BigDecimal price,String d,String l,int y,Brand b,CarType t,String img,CarRepository r){Car c=new Car();c.setName(n);c.setLicensePlate(plate);c.setDailyPrice(price);c.setDescription(d);c.setLocation(l);c.setModelYear(y);c.setBrand(b);c.setCarType(t);c.setImageUrl(img);r.save(c);}}
